function R = residuals_hyb(r,x,epsilon,omega,kinetic_profiles,q,qp,P0,P1,P2,M_profiles,dof_count,Nb,Sbc,equation_of_state)
	N = numel(r);
	Ns = numel(Sbc);
	nRes = 3+Nb+Ns;
	t2_c    = x(1:dof_count);
	delta_c = x(dof_count+1:2*dof_count);
	P_c = x(2*dof_count+1:3*dof_count);
	Bs_c    = reshape(x(3*dof_count+1:(3+Nb)*dof_count), [dof_count, 1, Nb]);
	Bs_flat   = reshape(Bs_c, size(Bs_c,1), []);        % dof_count x Ns
	S_unkn     = reshape(x((3+Nb)*dof_count+1:end), [dof_count-1, 1, Ns]);
	S_c     = cat(1, S_unkn, reshape(Sbc, [1, 1, Ns]));
	S_flat   = reshape(S_c, size(S_c,1), []);        % dof_count x Ns
	t2      = P0 * t2_c;
	t2p     = P1 * t2_c;
	delta   = P0 * delta_c;
	deltap  = P1 * delta_c;
	deltapp = P2 * delta_c;
	P   = P0 * P_c;
	Pp  = P1 * P_c;
	Ppp = P2 * P_c;
	Bs       = reshape(P0 * Bs_flat, N, 1, []);
	Bsp = reshape(P1 * Bs_flat, N, 1, []);
	S       = reshape(P0 * S_flat, N, 1, []);
	Sp = reshape(P1 * S_flat, N, 1, []);
	Spp = reshape(P2 * S_flat, N, 1, []);
	resTotal = zeros(nRes,N);
	ms = reshape(linspace(2,Ns+1,Ns), [1,1,Ns]);
	mb = reshape(0:(Nb-1), [1,1,Nb]);
	RR = 1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3);
	BB = 1 + epsilon.*sum(Bs.*cos(mb.*omega),3);

	[dbetapardB0, ...
        dbetapardr, dbetapardB, dbetapardR, ...
        d2betapardB2, d2betapardrdB, d2betapardRdB] = equation_of_state(kinetic_profiles,r,RR,BB);

	T1 = -(epsilon.^2.*P.*sin(omega)) - r.*sin(omega) + epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3);
	T2 = epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3);
	T3 = -(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3);
	T4 = sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(sin((-1 + ms).*omega).*Sp,3);
	T7 = r + epsilon.^2.*Pp.*r - deltap.*epsilon.*r.*cos(omega) - epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - epsilon.^3.*Pp.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.*r.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3)) - epsilon.*r.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*sum(sin((-1 + ms).*omega).*Sp,3) + epsilon.^2.*P.*(1 + epsilon.^2.*Pp - deltap.*epsilon.*cos(omega) + epsilon.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3));
	T8 = 1 - dbetapardB0.*epsilon.^2 + epsilon.^2.*t2;
	T11 = epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3));
	T14 = cos(omega) + epsilon.^2.*Pp.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3);
	T15 = -((1 + epsilon.^2.*Pp).*sin(omega)) + epsilon.*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3);
	T16 = 1./(r + epsilon.^2.*Pp.*r - deltap.*epsilon.*r.*cos(omega) - epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - epsilon.^3.*Pp.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.*r.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3)) - epsilon.*r.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*sum(sin((-1 + ms).*omega).*Sp,3) + epsilon.^2.*P.*(1 + epsilon.^2.*Pp - deltap.*epsilon.*cos(omega) + epsilon.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3)));
	T23 = sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3)) - sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(sin((-1 + ms).*omega).*Sp,3)) - (epsilon.^2.*P + r).*(-(deltap.*sin(omega)) + sin(omega).*sum(cos((-1 + ms).*omega).*Sp,3) + cos(omega).*sum(sin((-1 + ms).*omega).*Sp,3));
	T24 = (1 - dbetapardB0.*epsilon.^2 + epsilon.^2.*t2).^2;
	T25 = (r + epsilon.^2.*Pp.*r - deltap.*epsilon.*r.*cos(omega) - epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - epsilon.^3.*Pp.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.*r.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3)) - epsilon.*r.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*sum(sin((-1 + ms).*omega).*Sp,3) + epsilon.^2.*P.*(1 + epsilon.^2.*Pp - deltap.*epsilon.*cos(omega) + epsilon.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3))).^(-2);
	T34 = deltap.*epsilon.^2.*P.*cos(omega) + deltap.*r.*cos(omega) - sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - epsilon.^2.*Pp.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - sin(omega).*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - epsilon.^2.*Pp.*sin(omega).*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - epsilon.^2.*P.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - r.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) + sum(-((-1 + ms).^2.*cos((-1 + ms).*omega).*S),3).*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3)) - epsilon.^2.*P.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) - r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) - sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(cos(omega) + epsilon.^2.*Pp.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3)) + epsilon.^2.*P.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3) + r.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3) + epsilon.*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3).*sum(sin((-1 + ms).*omega).*Sp,3) - epsilon.^2.*P.*sin(omega).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3) - r.*sin(omega).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3) + epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3);
	T35 = deltap.*epsilon.^2.*P.*sin(omega) + deltap.*r.*sin(omega) - cos(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - epsilon.^2.*Pp.*cos(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + deltap.*epsilon.*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - cos(omega).*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - epsilon.^2.*Pp.*cos(omega).*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - epsilon.^2.*P.*sin(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - r.*sin(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.^2.*P.*sin(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) - r.*sin(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) + epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) - epsilon.^2.*P.*cos(omega).*sum(sin((-1 + ms).*omega).*Sp,3) - r.*cos(omega).*sum(sin((-1 + ms).*omega).*Sp,3) - sum(-((-1 + ms).^2.*cos((-1 + ms).*omega).*S),3).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(sin((-1 + ms).*omega).*Sp,3)) + epsilon.^2.*P.*cos(omega).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3) + r.*cos(omega).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3) + sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3));
	T36 = 2.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)).*(cos(omega) + epsilon.^2.*Pp.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3));
	T37 = 2.*(epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3));
	T40 = (-2.*r.^2.*sin(omega) - 2.*epsilon.^2.*Pp.*r.^2.*sin(omega) + 2.*deltap.*r.*RR.*sin(omega) + deltap.*epsilon.*r.^2.*sin(2.*omega) - 2.*RR.*sin(omega).*sum(-((-1 + ms).^2.*cos((-1 + ms).*omega).*S),3) - 2.*epsilon.^2.*Pp.*RR.*sin(omega).*sum(-((-1 + ms).^2.*cos((-1 + ms).*omega).*S),3) + 3.*epsilon.*r.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + 3.*epsilon.^3.*Pp.*r.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - 2.*deltap.*epsilon.^2.*r.*cos(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - 2.*RR.*cos(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - 2.*epsilon.^2.*Pp.*RR.*cos(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - epsilon.*r.*cos(2.*omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - epsilon.^3.*Pp.*r.*cos(2.*omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - 2.*epsilon.^2.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^4.*Pp.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 + 2.*deltap.*epsilon.*RR.*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - 2.*RR.*cos(omega).*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - 2.*epsilon.^2.*Pp.*RR.*cos(omega).*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - 2.*r.*RR.*sin(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*r.^2.*sin(2.*omega).*sum(cos((-1 + ms).*omega).*Sp,3) + 2.*epsilon.^2.*r.*cos(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*sum(cos((-1 + ms).*omega).*Sp,3) - 2.*epsilon.*RR.*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3).*sum(cos((-1 + ms).*omega).*Sp,3) - 2.*r.*RR.*sin(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) + 2.*epsilon.*RR.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) + epsilon.*r.^2.*sum(sin((-1 + ms).*omega).*Sp,3) - 2.*r.*RR.*cos(omega).*sum(sin((-1 + ms).*omega).*Sp,3) - epsilon.*r.^2.*cos(2.*omega).*sum(sin((-1 + ms).*omega).*Sp,3) + 2.*epsilon.*RR.*sum(-((-1 + ms).^2.*cos((-1 + ms).*omega).*S),3).*sum(sin((-1 + ms).*omega).*Sp,3) - 4.*epsilon.^2.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*sum(sin((-1 + ms).*omega).*Sp,3) + 2.*epsilon.^3.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2.*sum(sin((-1 + ms).*omega).*Sp,3) - 2.*epsilon.^4.*P.^2.*sin(omega).*(1 + epsilon.^2.*Pp - deltap.*epsilon.*cos(omega) + epsilon.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3)) + 2.*r.*RR.*cos(omega).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3) + 2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(-(deltap.*epsilon.^2.*r.*sin(omega)) + RR.*sin(omega) + epsilon.^2.*Pp.*RR.*sin(omega) + epsilon.*r.*cos(omega).*sin(omega) + epsilon.^3.*Pp.*r.*cos(omega).*sin(omega) + epsilon.^2.*r.*sin(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3)) - epsilon.*RR.*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3)) + epsilon.^2.*P.*(2.*epsilon.*sin(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3)) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*(-3 - 3.*epsilon.^2.*Pp + 2.*deltap.*epsilon.*cos(omega) + cos(2.*omega) + epsilon.^2.*Pp.*cos(2.*omega) - 2.*epsilon.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) + 4.*epsilon.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3)) - 2.*(2.*r.*sin(omega) + 2.*epsilon.^2.*Pp.*r.*sin(omega) - deltap.*RR.*sin(omega) - deltap.*epsilon.*r.*sin(2.*omega) + (RR + 2.*epsilon.*r.*cos(omega)).*sin(omega).*sum(cos((-1 + ms).*omega).*Sp,3) + RR.*sin(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) - epsilon.*r.*sum(sin((-1 + ms).*omega).*Sp,3) + RR.*cos(omega).*sum(sin((-1 + ms).*omega).*Sp,3) + epsilon.*r.*cos(2.*omega).*sum(sin((-1 + ms).*omega).*Sp,3) - RR.*cos(omega).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3))))./2.;
	T48 = ((BB.*d2betapardB2 - dbetapardB).*sum(-(mb.*Bs.*sin(mb.*omega)),3) - BB.*d2betapardRdB.*(epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)))./BB.^2;
	T49 = d2betapardrdB + d2betapardB2.*epsilon.*sum(Bsp.*cos(mb.*omega),3) + d2betapardRdB.*epsilon.*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3));

	resF = (1 - delta.*epsilon.^2 + epsilon.^3.*P.*cos(omega) + epsilon.*r.*cos(omega) + epsilon.^2.*sum(cos((-1 + ms).*omega).*S,3)).*((epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)).*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3)) + (epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(sin((-1 + ms).*omega).*Sp,3))).*(-(dbetapardR.*epsilon.*T3) + (T16.*(2.*RR.^2.*(dbetapardR.*epsilon.*RR.*T11.*T3.*T7 + RR.*(dbetapardr.*T11 + BB.*(BB.*epsilon.^2.*T23.*T48 - T11.*T49)).*T7 - BB.*dbetapardB.*(epsilon.^2.*T23.*T40 + RR.*(T1.*T15 + T14.*T2 - epsilon.*T34).*T7)) + (BB.*T24.*(-2.*BB.*epsilon.^2.*RR.*T23.*T48.*T7 + dbetapardB.*(RR.*(-2.*epsilon.*T34 + T36 + T37).*T7 + 2.*epsilon.*(epsilon.*T23.*T40 - T11.*T3.*T7))))./(BB - dbetapardB.*epsilon.^2).^2))./(2..*RR.^3.*T11) + (epsilon.*r.^2.*T16.*(epsilon.*T1.*T16.*T23 - RR.*T16.*T34 + epsilon.*RR.*T23.*T25.*T35).*T8.^2)./(q.^2.*RR.^3) + (BB.*T8.*(BB.*(BB - dbetapardB.*epsilon.^2).*t2p + T8.*(BB.*T49 - dbetapardB.*epsilon.*sum(Bsp.*cos(mb.*omega),3))))./((BB - dbetapardB.*epsilon.^2).^3.*RR.^2) + (r.*T16.*T8.*(-(qp.*r.*RR.*T11.*T16.*T8) + q.*(epsilon.^2.*r.*RR.*T11.*T16.*t2p + RR.*T11.*T16.*T8 + deltapp.*epsilon.*r.*RR.*T11.*T2.*T25.*T8 - epsilon.*r.*T11.*T16.*T3.*T8 - r.*RR.*T11.*T14.*T25.*T3.*T8 + r.*RR.*T16.*T36.*T8 + r.*RR.*T16.*T37.*T8 + r.*RR.*T11.*T15.*T25.*T4.*T8 - epsilon.^2.*Ppp.*r.*RR.*T11.*T2.*T25.*T8.*cos(omega) + epsilon.^2.*Ppp.*r.*RR.*T1.*T11.*T25.*T8.*sin(omega) - epsilon.*r.*RR.*T11.*T2.*T25.*T8.*sum(cos((-1 + ms).*omega).*Spp,3) - epsilon.*r.*RR.*T1.*T11.*T25.*T8.*sum(sin((-1 + ms).*omega).*Spp,3))))./(q.^3.*RR.^3));
	resB = (BB.^2.*(1 - T24./((BB - dbetapardB.*epsilon.^2).^2.*RR.^2)))./epsilon - (epsilon.*r.^2.*T11.*T24.*T25)./(q.^2.*RR.^2);
	resF_FFT = real(fft(resF, [], 2))/numel(omega);
	resB_FFT = real(fft(resB, [], 2))/numel(omega);
	mF = [0, 1, 2:(Ns+1)];
	rowsF = [1, 2, (2 + Nb + (2:(Ns+1)))];
	mB = 0:(Nb-1);
	rowsB = 3 + (1:Nb);
	resTotal(rowsF, :) = resF_FFT(:, mF + 1).';
	resTotal(rowsB, :) = resB_FFT(:, mB + 1).';
	resTotal(3,:) = mean((r - ((epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)).*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3)) + (epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(sin((-1 + ms).*omega).*Sp,3)))./RR)./epsilon.^2, 2);
	R = M_profiles * reshape(resTotal.', [], 1);
end
